fn skyFragment(uv: vec2<f32>) -> vec4<f32> {
    let cen = uv - vec2<f32>(0.5, 0.5);
    let corr = vec2<f32>(camera.aspect, 1.0);
    let rad = length(cen * corr);
    let topCol = vec3<f32>(0.0015, 0.0025, 0.0075);
    let botCol = vec3<f32>(0.009, 0.012, 0.028);
    let grad = mix(botCol, topCol, clamp(uv.y, 0.0, 1.0));
    let glowAmt = exp(-rad * rad * 5.5);
    let glowCol = vec3<f32>(0.016, 0.026, 0.062) * glowAmt;
    let faintBand = exp(-rad * rad * 18.0) * vec3<f32>(0.012, 0.016, 0.038);
    var col = grad + glowCol + faintBand;
    let vig = 1.0 - 0.62 * smoothstep(0.32, 1.05, rad);
    col = col * vig;
    let dith = fract(sin(dot(uv * 913.0, vec2<f32>(12.9898, 78.233))) * 43758.5453);
    col = col + (dith - 0.5) * 0.004;
    col = max(col, vec3<f32>(0.0, 0.0, 0.0));
    return vec4<f32>(col, 1.0);
}

fn h01(idx: u32, salt: u32) -> f32 {
    var h = idx + salt * 374761393u;
    h = (h ^ 61u) ^ (h >> 16u);
    h = h + (h << 3u);
    h = h ^ (h >> 4u);
    h = h * 668265263u;
    h = h ^ (h >> 15u);
    return f32(h & 65535u) / 65535.0;
}
fn seedGalaxy(index: u32) {
    let base = index * B_stars_STRIDE;
    let r1 = h01(index, 11u);
    let r2 = h01(index, 23u);
    let r3 = h01(index, 37u);
    let r4 = h01(index, 53u);
    let r5 = h01(index, 71u);
    let r6 = h01(index, 97u);
    var px = 0.0;
    var py = 0.0;
    var pz = 0.0;
    var sc = 0.05;
    var cr = 1.0;
    var cg = 1.0;
    var cb = 1.0;
    if (index < 3500u) {
        let theta = r2 * 6.2831853;
        let ca = 2.0 * r3 - 1.0;
        let cac = clamp(ca, -1.0, 1.0);
        let phi = acos(cac);
        let sp = sin(phi);
        let rr = 2.6 * pow(r1, 1.6);
        px = sp * cos(theta) * rr;
        pz = sp * sin(theta) * rr;
        py = cos(phi) * rr * 0.42 + (r4 - 0.5) * 0.12;
        sc = 0.035 + 0.05 * r4;
        let innerF = clamp(rr / 2.6, 0.0, 1.0);
        let bright = 0.85 + 0.55 * r5;
        cr = mix(1.0, 1.0, innerF) * bright;
        cg = mix(0.96, 0.68, innerF) * bright;
        cb = mix(0.88, 0.30, innerF) * bright;
    } else {
        let a = index - 3500u;
        let arm = a % 2u;
        let q = a / 2u;
        let tt = (f32(q) + 0.5) / 4250.0;
        let r0 = 2.1 + tt * 7.9;
        let dr = (r4 - 0.5) * (0.5 + tt * 1.4);
        let dAng = (r5 - 0.5) * (0.55 / (0.6 + tt * 1.8));
        let angBase = f32(arm) * 3.14159265 + tt * 3.9 + (r1 - 0.5) * 0.25;
        let rr2 = r0 + dr;
        let ang = angBase + dAng;
        var xx = cos(ang) * rr2;
        var zz = sin(ang) * rr2;
        let barBoost = 1.0 + 0.4 * max(0.0, 1.0 - tt * 4.0);
        xx = xx * barBoost;
        px = xx;
        pz = zz;
        let thick = 0.35 * (1.0 - tt * 0.7) + 0.08;
        py = (r6 - 0.5) * 2.0 * thick + (r2 - 0.5) * 0.06;
        sc = 0.032 + 0.038 * r2 + 0.012 * (1.0 - tt);
        let coreBlend = max(0.0, 1.0 - tt * 5.0);
        var br = mix(0.78, 0.45, tt);
        var bg = mix(0.86, 0.62, tt);
        var bb = mix(1.0, 1.0, tt);
        let tw = 0.85 + 0.3 * r3;
        br = br * tw;
        bg = bg * tw;
        bb = bb * tw;
        let gr = 1.0;
        let gg = 0.78;
        let gb = 0.45;
        cr = mix(br, gr, coreBlend * 0.85);
        cg = mix(bg, gg, coreBlend * 0.85);
        cb = mix(bb, gb, coreBlend * 0.85);
    }
    b_stars[base + 0u] = 0.0;
    b_stars[base + 1u] = px;
    b_stars[base + 2u] = py;
    b_stars[base + 3u] = pz;
    b_stars[base + 4u] = 0.0;
    b_stars[base + 5u] = 0.0;
    b_stars[base + 6u] = 0.0;
    b_stars[base + 7u] = 1.0;
    b_stars[base + 8u] = sc;
    b_stars[base + 9u] = sc;
    b_stars[base + 10u] = sc;
    b_stars[base + 11u] = cr;
    b_stars[base + 12u] = cg;
    b_stars[base + 13u] = cb;
}

fn spinGalaxy(index: u32) {
    let base = index * B_stars_STRIDE;
    let px = b_stars[base + 1u];
    let py = b_stars[base + 2u];
    let pz = b_stars[base + 3u];
    let rad = sqrt(px * px + pz * pz);
    let omega = 0.052 + 0.06 * exp(-rad * 0.5);
    let ang = omega * sim.dt;
    let ca = cos(ang);
    let sa = sin(ang);
    let nx = px * ca + pz * sa;
    let nz = -px * sa + pz * ca;
    b_stars[base + 1u] = nx;
    b_stars[base + 2u] = py;
    b_stars[base + 3u] = nz;
    let armMix = clamp((rad - 1.5) / 3.0, 0.0, 1.0);
    let amp = 0.03 + 0.05 * armMix;
    let phase = f32(index) * 1.7 + rad * 2.0;
    let currS = sin(sim.time * 2.5 + phase);
    let prevS = sin((sim.time - sim.dt) * 2.5 + phase);
    let currF = 1.0 + amp * currS;
    let prevF = 1.0 + amp * prevS;
    let ratio = currF / prevF;
    let sx = b_stars[base + 8u];
    let sy = b_stars[base + 9u];
    let sz = b_stars[base + 10u];
    b_stars[base + 8u] = sx * ratio;
    b_stars[base + 9u] = sy * ratio;
    b_stars[base + 10u] = sz * ratio;
}
